entries[40767] = { ["name"] = "Überschallbooster", ["text"] = "Wird beim Anlegen gebunden\nSchmuck\n+81 Ausdauer\nBenötigt Ingenieurskunst (390)\nAnlegen: In manchen Fällen schärft der Lärm von Nahkämpfen Euer Schallbewusstsein und erhöht 10 sec lang Eure Angriffskraft um 430. Dieser Effekt kann pro Minute nur einmal auftreten. (Procchance: 35%, 50s Abklingzeit)" }
entries[40768] = { ["name"] = "MOLL-E", ["text"] = "Spielzeug\nBenötigt Ingenieurskunst (425)\nBenutzen: Erstellt 10 min lang einen tragbaren Briefkasten. MOLL-E wird nach seiner Nutzung nicht zerstört. (2 Std. Abklingzeit)\n\"Mobiler optimierter Liebesbrief- und Lieferungsextraktor\"" }
entries[40769] = { ["name"] = "Konstruktionsset: Schrottbot", ["text"] = "Benötigt Ingenieurskunst (425)\nBenutzen: Erstellt einen mechanischen Schrottbot, der Ausrüstung repariert und fast alles kauft. Nach 5 min verschwindet er. (15 Min Abklingzeit)" }
entries[40771] = { ["name"] = "Kobaltsplitterbombe", ["text"] = "Benötigt Ingenieurskunst (330)\nBenutzen: Fügt 750 to 1000 Feuerschaden zu und macht Ziele 3 sec lang in einem Radius von 3 Metern handlungsunfähig. Jeglicher Schaden wird den Effekt abbrechen. (1 Min Abklingzeit)" }
entries[40772] = { ["name"] = "Gnomisches Armeemesser", ["text"] = "Benutzen: Ein Großmeister der Ingenieurskunst kann die Batterien des Messers überladen, um zu versuchen, einen toten Spieler ins Leben zurückzurufen. Kann nicht im Kampf verwendet werden. (30 Min Abklingzeit)\n\"Beinhaltet einen gyromatischen Mikroregler, einen Bogenlichtschraubenschlüssel, Feuerstein und Zunder, einen Schmiedehammer, eine Spitzhacke und ein Kürschnermesser.\"" }
entries[40773] = { ["name"] = "Meisterlicher Feuerstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Erhöht bei Anwendung auf eine Waffe den Schaden direkter Schadenszauber um 1% und erhöht die kritische Zaubertrefferwertung um 35. Hält 1 Stunde lang an.\n5 Aufladungen" }
entries[40774] = { ["name"] = "Meisterlicher Zauberstein", ["text"] = "Benötigt Stufe 45\nBenutzen: Erhöht bei Anwendung auf eine Waffe die Zaubermacht regelmäßiger Schadenzauber um 50 und erhöht die Zaubertempowertung um 50. Hält 1 Stunde lang an.\n5 Aufladungen" }
entries[40775] = { ["name"] = "Geflügelter Greif der Schwarzen Klinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittierKlassen: Todesritter\nBenötigt Stufe 60\nBenötigt Reiten (225)\nBenutzen: Geschwindigkeit hängt von der Reitfähigkeit ab.\nBeschwört Euren geflügelten Greif der Schwarzen Klinge oder gibt ihn wieder frei. Dieses Reittier kann nur in der Scherbenwelt und in Nordend beschworen werden. Die Fluggeschwindigkeit dieses Reittieres ist von Eurer Reitfertigkeit abhängig." }
entries[40776] = { ["name"] = "Persönlicher elektromagnetischer Pulsgenerator", ["text"] = "Benötigt Ingenieurskunst (375)\nBenutzen: Bringt an einem Gürtel dauerhaft einen elektromagnetischen Pulsgenerator an, der es einem geschickten Ingenieur bei Aktivierung gestattet, nahe mechanische Einheiten zu verwirren.\n\nKann nur an Euren eigenen Gürtel angebracht werden und er wird dadurch seelengebunden." }
entries[40777] = { ["name"] = "Eisbärengeschirr", ["text"] = "Wird beim Aufheben gebunden\nReittier\nBenötigt Stufe 60\nBenötigt Reiten (150)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren weißen Eisbär oder gibt ihn frei. Das ist ein sehr schnelles Reittier." }
entries[40778] = { ["name"] = "Plattenbrustharnisch des grausamen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nBrust Platte\n2166 Rüstung\n+62 Stärke\n+115 Ausdauer\n\nRoter Sockel\nGelber Sockel\nSockelbonus: +6 Abhärtungswertung\n\nHaltbarkeit 135 / 135Klassen: Krieger\nBenötigt Stufe 80\nAnlegen: Erhöht die kritische Trefferwertung um 36.\nAnlegen: Erhöht Eure Abhärtungswertung um 52.\n\n[Savage Gladiator's Battlegear] (0/5)\nPlattenbrustharnisch des grausamen Gladiators\nPlattenstulpen des grausamen Gladiators\nPlattenhelm des grausamen Gladiators\nPlattenbeinschützer des grausamen Gladiators\nPlattenschultern des grausamen Gladiators\n(2) Set : +100 Abhärtungswertung.\n(2) Set : Erhöht die Angriffskraft um 50.\n(4) Set : Verringert die Abklingzeit Eurer Fähigkeit 'Abfangen' um 5 Sek.\n(4) Set : Erhöht die Angriffskraft um 150." }
