entries[41091] = { ["name"] = "Handmontierte Pyrorakete", ["text"] = "Benötigt Ingenieurskunst (375)\nBenutzen: Bringt an einem Paar Handschuhe dauerhaft einen Pyroraketenwerfer an, der es einem geschickten Ingenieur gestattet, eine Rakete abzuschießen, die auf Distanz 1654 to 2020 Feuerschaden verursacht. Kann nur einmal alle 45 Sek. abgefeuert werden.\n\nKann nur an Eure eigenen Handschuhe angebracht werden und sie werden dadurch seelengebunden." }
