entries[41118] = { ["name"] = "Nitrobooster", ["text"] = "Benötigt Ingenieurskunst (375)\nBenutzen: Bringt an einem Paar Stiefel dauerhaft Nitrobooster an, die die kritische Trefferwertung um 24 erhöhen und die es Euch gestatten, Euer Lauftempo 5 sec lang erheblich zu erhöhen.\n\nDie Booster können nur einmal alle 3 Minuten genutzt werden und benötigen eine Ingenieursfähigkeit von mindestens 400." }
entries[41119] = { ["name"] = "Saronitbombe", ["text"] = "Benötigt Ingenieurskunst (350)\nBenutzen: Verursacht bei Zielen in einem Radius von 10 Metern 1150 to 1500 Feuerschaden. Die Explosion ist stark genug, um moderaten Belagerungsschaden zu verursachen. (1 Min Abklingzeit)" }
entries[41120] = { ["name"] = "Pläne: Verstärkte Kobaltbeinplatten", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst (375)\nBenutzen: Lehrt Euch die Herstellung verstärkter Kobaltbeinplatten.\nVerstärkte Kobaltbeinplatten\nWird beim Anlegen gebunden\nBeine Platte\n1321 Rüstung\n+48 Stärke\n+63 Ausdauer\nHaltbarkeit 85 / 85\nBenötigt Stufe 76\nAnlegen: Erhöht die kritische Trefferwertung um 31.\nAnlegen: Erhöht Eure Abhärtungswertung um 41.\nBenötigt Kobaltbarren (8), Kristallisiertes Wasser (2)" }
entries[41121] = { ["name"] = "Gnomischer Blitzgenerator", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\nBenötigt Ingenieurskunst (425)\nAnlegen: Erhöht die kritische Trefferwertung um 84.\nBenutzen: Erzeugt einen Blitzstrahl, der einen Feind für 1530 to 1870 Naturschaden trifft. Das ganze Gehäuse des Geräts ist aus Metall... (1 Min Abklingzeit)\n\"Garantiert sicher!\"" }
